const items = JSON.parse(fs.readFileSync('/tmp/scout_feeds/parsed.json', 'utf8'));

// Filter items within last 24-48 hours.
const filtered = items.filter(item => {
  const pd = item.pubDate.toLowerCase();
  return pd.includes('02 jun 2026') || pd.includes('01 jun 2026') || pd.includes('jun 2, 2026') || pd.includes('jun 1, 2026') || pd.includes('2026-06-02') || pd.includes('2026-06-01');
});

// We want to check candidate topics/URLs.
// Let's first group the main repeating topics.
// 1. Mt. Gox moves $739M in Bitcoin (10,422 BTC)
// 2. Strategy's Bitcoin sale (32 BTC for $2.5 million / Polymarket disputes / shares slide)
// 3. MoneyGram launches stablecoin MGUSD on Stellar
// 4. TON (The Open Network) plans to rebrand to Gram / pumps 15%
// 5. Binance launches tokenized US stocks/ETFs trading (bStocks)
// 6. Robinhood enters Canada with WonderFi acquisition ($180 million)
// 7. Radiant Capital winding down operations
// 8. Bitcoin dropping below $70k / $69k as Saylor sale spooks investors

// Let's define the primary URLs for these and run check_history on them.
const candidates = [
  { name: "Mt. Gox moves 10,422 bitcoin worth $739 million", url: "https://www.coindesk.com/markets/2026/06/02/mt-gox-moves-10422-bitcoin-worth-usd739-million-to-a-new-wallet-as-deadline-nears" },
  { name: "MoneyGram launches stablecoin on Stellar", url: "https://www.coindesk.com/business/2026/06/02/moneygram-launches-stablecoin-on-stellar-joining-rush-toward-digital-dollar-payments" },
  { name: "Strategy sold 32 BTC / Polymarket bets dispute", url: "https://www.coindesk.com/markets/2026/06/02/strategy-sold-bitcoin-in-late-may-and-told-the-market-in-june-here-s-how-polymarket-bettors-are-fighting-over-when-it-counts" },
  { name: "TON rebrand to Gram / TON pumps 15%", url: "https://cointelegraph.com/news/the-open-network-ton-native-currency-plans-to-rebrand-to-gram" },
  { name: "Binance launches tokenized US stock trading", url: "https://cointelegraph.com/news/binance-launches-tokenized-stocks-245-trading" },
  { name: "Robinhood enters Canada via WonderFi acquisition", url: "https://cointelegraph.com/news/robinhood-enters-canada-crypto-market-wonderfi-acquisition" },
  { name: "Radiant Capital winding down after failing to recover from hack", url: "https://cointelegraph.com/news/defi-protocol-radiant-to-wind-down-after-failing-to-recover-from-2024-hack" }
];

console.log("Checking history database for candidates:");
for (const cand of candidates) {
  try {
    const cmd = `bash ~/.openclaw/workspace-researcher/skills/history/article_history.sh check "${cand.url}"`;
    const res = execSync(cmd).toString().trim();
    console.log(`- [${res}] ${cand.name} (${cand.url})`);
  } catch (err) {
    console.error(`Error checking ${cand.name}: ${err.message}`);
  }
}

const fs = require('fs');

const items = JSON.parse(fs.readFileSync('/tmp/scout_feeds/parsed.json', 'utf8'));

// Filter items within last 24-48 hours.
const filtered = items.filter(item => {
  const pd = item.pubDate.toLowerCase();
  return pd.includes('02 jun 2026') || pd.includes('01 jun 2026') || pd.includes('jun 2, 2026') || pd.includes('jun 1, 2026') || pd.includes('2026-06-02') || pd.includes('2026-06-01');
});

// Let's filter items with "MoneyGram" or " Stellar" or "MGUSD"
console.log("=== MoneyGram / Stellar articles ===");
filtered.filter(item => {
  const text = (item.title + " " + item.desc).toLowerCase();
  return text.includes("moneygram") || text.includes("stellar") || text.includes("mgusd");
}).forEach(item => {
  console.log(`[${item.site}] ${item.title}\n  URL: ${item.link}\n`);
});

// Let's filter items with "Mt. Gox" or "Gox"
console.log("=== Mt. Gox articles ===");
filtered.filter(item => {
  const text = (item.title + " " + item.desc).toLowerCase();
  return text.includes("mt. gox") || text.includes("mt gox") || text.includes("gox");
}).forEach(item => {
  console.log(`[${item.site}] ${item.title}\n  URL: ${item.link}\n`);
});

// Let's filter items with "TON" or "Telegram" or "Gram" (excluding MoneyGram / Gram of course or carefully)
